SELECT "APPLICATION" AS "APPLICATION", COUNT(*) AS count, sum("JOB_DURATION_d") AS "SUM(JOB_DURATION_d)" 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' AND "ENVIRONMENT_TYPE" IN ('PROD', 'UAT') GROUP BY "APPLICATION" ORDER BY COUNT(*) DESC 
 LIMIT 5;

SELECT DATE_TRUNC('hour', "@timestamp_date") AS "@timestamp_date", "APPLICATION" AS "APPLICATION", COUNT(*) AS count, sum("JOB_DURATION_d") AS "SUM(JOB_DURATION_d)" 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' AND "ENVIRONMENT_TYPE" IN ('PROD', 'UAT') AND ("APPLICATION" = 'BILLING' OR "APPLICATION" = 'PAYROLL' OR "APPLICATION" = 'ORDERS' OR "APPLICATION" = 'COMPUTE' OR "APPLICATION" = 'ANALYTICS') GROUP BY DATE_TRUNC('hour', "@timestamp_date"), "APPLICATION" ORDER BY count DESC 
 LIMIT 10000;